const STATUS_TYPES = new Set(["passed", "failed", "incomplete"]);
const SENSITIVE_ENV_RE = /(token|secret|password|credential|api[_-]?key)/i;
const SAFE_SEGMENT_RE = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
